INSERT INTO questions (id, group_id, question_type, question_text, options, correct_answer, points, order_index) VALUES ('174b3419-db8a-4c27-a27b-1eceb403dccb', '33ecdbaa-fb31-4554-aebb-567bfd0eddb7', 'essay', '<h2 data-section-id="azh5be" data-start="347" data-end="369">Dịch sang tiếng Anh</h2><h2 data-section-id="azh5be" data-start="347" data-end="369"><b>2) Social ostracism</b></h2>n<p data-start="371" data-end="497">Những học sinh có quan điểm khác biệt thường phải đối mặt với sự tẩy chay xã hội trong môi trường học đường.</p>n<p data-start="499" data-end="511"><strong data-start="499" data-end="509">Gợi ý:</strong></p>n<ul data-start="512" data-end="586">n<li data-section-id="qpldvj" data-start="512" data-end="526"><span style="color: rgb(15, 23, 41); font-size: 0.875rem;">students with unconventional views</span></li></ul>', '["", "", "", ""]', '', 1, 2); -- Classification: PROTECTED_NEW_ROW_REQUIRED (Ans: 1)
