INSERT INTO questions (id, group_id, question_type, question_text, options, correct_answer, points, order_index) VALUES ('dd12e2ca-8ca4-42fe-aed6-7d704851d039', 'ef21db03-ea09-401d-999f-91f7fdb7d2d5', 'fill_blank', '<div><b>Phần 1: Điền vào chỗ trống (Fill in the blanks)</b></div><div>Chia động từ nếu cần thiết.</div><div><br></div><div>1. To become a doctor, one must study hard to&nbsp;<span style="color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px; background-color: rgb(243, 245, 247);">[BLANK]</span>&nbsp;of the university.</div><div><br></div><div>2. The&nbsp;<span style="color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px; background-color: rgb(243, 245, 247);">[BLANK]</span>&nbsp;medicine has led to more rigorous standards for practitioners.</div><div><br></div><div>3. Modern technology has&nbsp;<span style="color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px; background-color: rgb(243, 245, 247);">[BLANK]</span>, from how we work to how we sleep.</div><div><br></div><div>4. He didn''t know what to write about, so he&nbsp;<span style="color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px; background-color: rgb(243, 245, 247);">[BLANK]</span>&nbsp;the latest news headlines.</div><div><br></div><div>5. In this massive library, you can find books about&nbsp;<span style="color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px; background-color: rgb(243, 245, 247);">[BLANK]</span>, from ancient history to AI.</div><div><br></div><div>6. Before you can attend the lectures, you need to&nbsp;<span style="background-color: rgb(243, 245, 247); color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px;">[BLANK]</span><span style="font-size: 0.875rem; color: rgb(15, 23, 41);">&nbsp;on the student portal.</span></div><div><br></div><div>7. Success in any&nbsp;<span style="background-color: rgb(243, 245, 247); color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px;">[BLANK]&nbsp;</span><span style="font-size: 0.875rem; color: rgb(15, 23, 41);">requires both passion and a strong work ethic.</span></div><div><br></div><div>8. The old carpenter taught his apprentice all the&nbsp;<span style="background-color: rgb(243, 245, 247); color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px;">[BLANK]</span><span style="font-size: 0.875rem; color: rgb(15, 23, 41);">&nbsp;that aren''t found in textbooks.</span></div><div><br></div><div>9. Although the rule seems strange, the university still&nbsp;<span style="background-color: rgb(243, 245, 247); color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px;">[BLANK]</span></div><div><br></div><div>10. A true leader always acts&nbsp;<span style="color: rgb(20, 184, 165); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, &quot;Liberation Mono&quot;, &quot;Courier New&quot;, monospace; font-size: 10px; background-color: rgb(243, 245, 247);">[BLANK]</span>, even when no one is watching.</div>', '["", "", "", ""]', '["meet the academic requirements","increasing professionalization of","crept into every aspect of life","took his cue from","everything under the sun","sign up for a course","field of knowledge | professional endeavor","tricks of the trade","has it on the books","in a principled fashion"]', 1, 0); -- Classification: SAFE_NEW_ROW_REQUIRED (Ans: 0)
